-- Jeu de LecteurRemplacementActeur / EcrivainRemplacementActeur (« Remplacer un acteur », PROC_SUPP_ACTEUR_JUD), lot 14 du plan-676a4b19.
-- Identifiants 24005xx, abreges « ...14... ». Les tables de liaison des cinq types d'acteurs (LiaisonsActeur.cs) sont creees par les jeux
-- joues avant (PROC_CHM, PROC_COMPO, PROC_COURRIERM, PROC_DEST_REDA, PROC_GCONV, PROC_RAPPACTEUR...) ; ce jeu ajoute les colonnes qui
-- manquent (nullables : les INSERT des autres jeux ne les nomment pas), et cree celles qu'aucun jeu ne cree avant lui : INSTANCE_JUGE (la
-- definition de PROC_XXAFF.sql, joue apres, plus JUGIN_ID_JUG), DEMAT_CFEC et INTERVENANT_PC (aucun autre jeu). Les lignes : un juge lie
-- par deux « juges d'instance » (INSTANCE_JUGE, sans lecteur ailleurs) aux affaires de PROC_IMPLEG.sql, son remplacant actif et un juge
-- inactif ; un intervenant PC lie a la PC 1400101 de PROC_CHM.sql et son remplacant ; un mandataire PC lie par un depot CFEC et son
-- remplacant ; un remplacement deja fait (ACTEUR_SUPP).
IF COL_LENGTH('v2.JUGE', 'JUG_ABREGE') IS NULL ALTER TABLE v2.JUGE ADD JUG_ABREGE varchar(16) NULL;
IF COL_LENGTH('v2.JUGE', 'JUG_ACTIF') IS NULL ALTER TABLE v2.JUGE ADD JUG_ACTIF bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_ABREGE') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_ABREGE varchar(16) NULL;
IF COL_LENGTH('v2.MANDATAIRE_PC', 'MNDPC_ACTIF') IS NULL ALTER TABLE v2.MANDATAIRE_PC ADD MNDPC_ACTIF bit NOT NULL DEFAULT (1);
IF COL_LENGTH('v2.INTERVENANT_PC_REPER', 'INTRPR_ABREGE') IS NULL ALTER TABLE v2.INTERVENANT_PC_REPER ADD INTRPR_ABREGE varchar(16) NULL;
IF COL_LENGTH('v2.INTERVENANT_PC_REPER', 'INTRPR_COMPLEMENT_NOM') IS NULL ALTER TABLE v2.INTERVENANT_PC_REPER ADD INTRPR_COMPLEMENT_NOM varchar(35) NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_PRQTR') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_PRQTR int NULL;
IF COL_LENGTH('v2.AUDIENCE_CABINET', 'AUDNC_ID_GRASS') IS NULL ALTER TABLE v2.AUDIENCE_CABINET ADD AUDNC_ID_GRASS int NULL;
IF COL_LENGTH('v2.INSTANCE', 'INSTN_ID_JUG') IS NULL ALTER TABLE v2.INSTANCE ADD INSTN_ID_JUG int NULL;
IF COL_LENGTH('v2.MESURE', 'MSINS_ID_JUG') IS NULL ALTER TABLE v2.MESURE ADD MSINS_ID_JUG int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_JUG') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_JUG int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_GRASS') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_GRASS int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_DEPOSANT_GED') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_DEPOSANT_GED int NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_ID_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_ID_DEPOSANT_GED int NULL;
IF COL_LENGTH('v2.EVENEMENT_PROCEDURE', 'EVNPR_TYPE_DEPOSANT_GED') IS NULL ALTER TABLE v2.EVENEMENT_PROCEDURE ADD EVNPR_TYPE_DEPOSANT_GED varchar(50) NULL;
IF COL_LENGTH('v2.VIDIGED_INDEX', 'VGIDX_ID_DEPOSANT') IS NULL ALTER TABLE v2.VIDIGED_INDEX ADD VGIDX_ID_DEPOSANT int NULL;
IF COL_LENGTH('v2.VIDIGED_INDEX', 'VGIDX_TYPE_DEPOSANT') IS NULL ALTER TABLE v2.VIDIGED_INDEX ADD VGIDX_TYPE_DEPOSANT varchar(50) NULL;
IF COL_LENGTH('v2.PAYEUR', 'PYEUR_ID_MNDPC') IS NULL ALTER TABLE v2.PAYEUR ADD PYEUR_ID_MNDPC int NULL;
IF OBJECT_ID(N'v2.INSTANCE_JUGE') IS NULL
    CREATE TABLE v2.INSTANCE_JUGE (JUGIN_ID_JUGIN int NOT NULL PRIMARY KEY, JUGIN_ID_INSTN int NOT NULL);
IF COL_LENGTH('v2.INSTANCE_JUGE', 'JUGIN_ID_JUG') IS NULL ALTER TABLE v2.INSTANCE_JUGE ADD JUGIN_ID_JUG int NULL;
IF OBJECT_ID(N'v2.DEMAT_CFEC') IS NULL
    CREATE TABLE v2.DEMAT_CFEC (CFEC_ID_CFEC int NOT NULL PRIMARY KEY, CFEC_ID_MANDATAIRE_PC int NULL);
IF OBJECT_ID(N'v2.INTERVENANT_PC') IS NULL
    CREATE TABLE v2.INTERVENANT_PC (INTRP_ID_INTRP int NOT NULL PRIMARY KEY, INTRP_ID_PRCLL int NOT NULL, INTRP_NOM varchar(35) NOT NULL,
        INTRP_ID_INTRPR int NULL);

